class Solution:
    def bestTower(self, towers: List[List[int]], center: List[int], radius: int) -> List[int]:
        cx, cy = center
        best = None
        for x, y, q in towers:
            if abs(x - cx) + abs(y - cy) <= radius:
                cand = (-q, x, y)
                if best is None or cand < best:
                    best = cand
        return [-1, -1] if best is None else [best[1], best[2]]

