class Solution {
    public int[] bestTower(int[][] towers, int[] center, int radius) {
        int cx = center[0], cy = center[1];
        boolean found = false;
        long best = 0;
        int bx = 0, by = 0;
        for (int[] t : towers) {
            int x = t[0], y = t[1], q = t[2];
            if (Math.abs(x - cx) + Math.abs(y - cy) <= radius) {
                long cand = ((long)(Integer.MAX_VALUE - q) << 40) | ((long)x << 20) | y;
                if (!found || cand < best) { best = cand; bx = x; by = y; found = true; }
            }
        }
        return found ? new int[]{bx, by} : new int[]{-1, -1};
    }
}

