var bestTower = function(towers, center, radius) {
    const [cx, cy] = center;
    let best = null;
    for (const [x, y, q] of towers) {
        if (Math.abs(x - cx) + Math.abs(y - cy) <= radius) {
            const cand = [-q, x, y];
            if (best === null || cand[0] < best[0] ||
               (cand[0] === best[0] && (cand[1] < best[1] ||
               (cand[1] === best[1] && cand[2] < best[2])))) {
                best = cand;
            }
        }
    }
    return best === null ? [-1, -1] : [best[1], best[2]];
};
